<?php
$counts = $pdo->query("SELECT
    (SELECT COUNT(*) FROM tbl_rental) AS rentals,
    (SELECT COUNT(*) FROM tbl_rental WHERE rental_status IN ('Pending','Active','Late')) AS open_rentals,
    (SELECT COUNT(*) FROM tbl_car) AS vehicles,
    (SELECT COUNT(*) FROM tbl_customer) AS customers,
    (SELECT COALESCE(SUM(pay_amount),0) FROM tbl_payment WHERE created_at >= DATE_FORMAT(CURDATE(),'%Y-%m-01')) AS month_payments,
    (SELECT COALESCE(SUM(i.invoice_amount-COALESCE(p.paid,0)),0) FROM tbl_invoice i LEFT JOIN (SELECT invoice_id,SUM(pay_amount) paid FROM tbl_payment GROUP BY invoice_id) p ON p.invoice_id=i.invoice_id WHERE i.invoice_status<>'Paid') AS unpaid")->fetch();
$monthlyRows = $pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') AS month, SUM(pay_amount) AS amount FROM tbl_payment WHERE created_at >= DATE_SUB(DATE_FORMAT(CURDATE(),'%Y-%m-01'), INTERVAL 5 MONTH) GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month")->fetchAll();
$paymentsByMonth = array_column($monthlyRows, 'amount', 'month');
$monthly = [];
for ($offset = 5; $offset >= 0; $offset--) {
    $month = (new DateTimeImmutable('first day of this month'))->modify("-{$offset} months");
    $key = $month->format('Y-m');
    $monthly[] = ['month' => $key, 'amount' => (float) ($paymentsByMonth[$key] ?? 0)];
}
$fleetBreakdown = $pdo->query('SELECT car_status,COUNT(*) AS total FROM tbl_car GROUP BY car_status ORDER BY total DESC')->fetchAll();
$rentalBreakdown = $pdo->query("SELECT rental_status,COUNT(*) AS total FROM tbl_rental GROUP BY rental_status ORDER BY FIELD(rental_status,'Pending','Active','Late','Completed','Dismissed')")->fetchAll();
$topCustomers = $pdo->query("SELECT c.customer_id,c.first_name,c.last_name,COUNT(r.rental_id) AS rentals,COALESCE(SUM(r.total_amount),0) AS amount FROM tbl_customer c JOIN tbl_rental r ON r.customer_id=c.customer_id GROUP BY c.customer_id ORDER BY rentals DESC,amount DESC LIMIT 5")->fetchAll();
$peak = max(1.0, ...array_column($monthly, 'amount'));
$fleetTotal = max(1, array_sum(array_column($fleetBreakdown, 'total')));
$rentalTotal = max(1, array_sum(array_column($rentalBreakdown, 'total')));
?>
<div class="page-heading"><div><p class="eyebrow">INSIGHTS FOR YOUR BUSINESS</p><h1>Reports</h1><p class="heading-copy">A clear view of fleet usage, customer activity, and collections.</p></div><div class="heading-actions"><a class="button button-secondary" href="index.php?page=reports&export=rentals">↓ Rental CSV</a><a class="button button-secondary" href="index.php?page=reports&export=payments">↓ Payment CSV</a></div></div>
<div class="report-metrics"><article class="report-metric"><span>All rentals</span><strong><?= e($counts['rentals']) ?></strong><small><?= e($counts['open_rentals']) ?> reservations and rentals currently open</small></article><article class="report-metric"><span>Fleet size</span><strong><?= e($counts['vehicles']) ?></strong><small>Registered vehicles</small></article><article class="report-metric"><span>Customers</span><strong><?= e($counts['customers']) ?></strong><small>Customer records</small></article><article class="report-metric"><span>Collected this month</span><strong><?= e(money($counts['month_payments'])) ?></strong><small><?= e(money($counts['unpaid'])) ?> outstanding across invoices</small></article></div>
<div class="report-grid">
<section class="panel chart-panel"><div class="panel-heading"><div><h2>Collections over time</h2><p>Payments received by month · last six months.</p></div></div><div class="chart-area"><?php foreach ($monthly as $month): $width = $month['amount'] > 0 ? max(4, (int) round(($month['amount'] / $peak) * 100)) : 0; ?><div class="chart-row"><span><?= e(date('M Y', strtotime($month['month'] . '-01'))) ?></span><div class="chart-track" role="img" aria-label="<?= e(money($month['amount'])) ?> collected"><i style="width:<?= $width ?>%"></i></div><strong><?= e(money($month['amount'])) ?></strong></div><?php endforeach; ?></div></section>
<section class="panel chart-panel"><div class="panel-heading"><div><h2>Fleet availability</h2><p>Vehicles by current status.</p></div></div><div class="fleet-breakdown"><?php if (!$fleetBreakdown): ?><div class="empty-state"><strong>No vehicle data yet</strong><span>Add vehicles to see availability.</span></div><?php endif; ?><?php foreach ($fleetBreakdown as $row): $share = (int) round(((int) $row['total'] / $fleetTotal) * 100); ?><div class="fleet-row"><div class="fleet-row-label"><span><?= render_status($row['car_status']) ?></span><strong><?= (int) $row['total'] ?></strong></div><div class="status-chart-track"><i class="fleet-chart-bar" style="width:<?= $share ?>%"></i></div></div><?php endforeach; ?></div></section>
<section class="panel chart-panel"><div class="panel-heading"><div><h2>Rental status</h2><p>Reservations and rentals grouped by workflow stage.</p></div></div><div class="status-chart" role="img" aria-label="Rental counts grouped by status"><?php if (!$rentalBreakdown): ?><div class="empty-state"><strong>No rental activity yet</strong><span>Reservations will appear here.</span></div><?php endif; ?><?php foreach ($rentalBreakdown as $row): $share = (int) round(((int) $row['total'] / $rentalTotal) * 100); ?><div class="status-chart-row"><div><span><?= render_status($row['rental_status']) ?></span><strong><?= (int) $row['total'] ?></strong></div><div class="status-chart-track"><i class="status-chart-<?= e(strtolower($row['rental_status'])) ?>" style="width:<?= $share ?>%"></i></div></div><?php endforeach; ?></div></section>
</div>
<section class="panel"><div class="panel-heading"><div><h2>Top customers</h2><p>Ranked by number of rentals.</p></div><a href="index.php?page=customers" class="text-link">Customer directory →</a></div><div class="table-wrap"><table><thead><tr><th>RANK</th><th>CUSTOMER</th><th>RENTALS</th><th>RENTAL TOTAL</th></tr></thead><tbody><?php if (!$topCustomers): ?><tr><td colspan="4"><div class="empty-state"><strong>No customer rentals yet</strong><span>Customer activity will appear as you process rentals.</span></div></td></tr><?php endif; ?><?php foreach ($topCustomers as $index => $customer): ?><tr><td><span class="rank-number"><?= $index + 1 ?></span></td><td><a class="table-primary" href="index.php?page=customers&edit=<?= (int) $customer['customer_id'] ?>"><?= e($customer['first_name'] . ' ' . $customer['last_name']) ?></a></td><td><?= (int) $customer['rentals'] ?></td><td><?= e(money($customer['amount'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
